            if (expectedEntries === 0) {
                status = 'no_students';
            }
            else if (allExpectedPublished &&
                missingEntries === 0 &&
                !hasIncompleteCards) {
                status = 'published';
            }
            else if (allExpectedGenerated &&
                missingEntries === 0 &&
                !hasIncompleteCards &&
                assessmentReadiness.missingScores === 0) {
                status = 'ready';
            }
