            const bRoll = Number.parseInt(b.student.studentProfile?.rollNumber || '', 10);
            const aRank = Number.isNaN(aRoll) ? Number.POSITIVE_INFINITY : aRoll;
            const bRank = Number.isNaN(bRoll) ? Number.POSITIVE_INFINITY : bRoll;
